import pathlib
p = pathlib.Path("packages/infrastructure/src/directus/client.ts")
t = p.read_text()

old = """async function userExists(baseUrl: string, token: string, userId: string): Promise<boolean> {
  try {
    await directusRequest(baseUrl, token, "GET", `/users/${userId}?fields=id`);
    return true;
  } catch (error) {
    if (!isNotFound(error)) throw error;
    return false;
  }
}"""

new = """async function userExists(baseUrl: string, token: string, userId: string): Promise<boolean> {
  try {
    await directusRequest(baseUrl, token, "GET", `/users/${userId}?fields=id`);
    return true;
  } catch (error) {
    // Directus answers 403 rather than 404 for a user id that is not there, even to an admin - it
    // will not confirm existence either way. A caller that just authenticated and can list users
    // therefore reads both as absent; a real credential failure surfaces on the next request.
    if (!isNotFound(error) && !isForbidden(error)) throw error;
    return false;
  }
}"""
assert t.count(old) == 1, t.count(old)
t = t.replace(old, new)

old2 = """function isNotFound(error: unknown): boolean {
  return error instanceof DirectusHttpError && error.status === 404;
}"""
new2 = """function isNotFound(error: unknown): boolean {
  return error instanceof DirectusHttpError && error.status === 404;
}

function isForbidden(error: unknown): boolean {
  return error instanceof DirectusHttpError && error.status === 403;
}"""
assert t.count(old2) == 1, t.count(old2)
p.write_text(t.replace(old2, new2))
print("patched")
